import { useEffect, useState } from "react";
import { useRuntime } from "../RuntimeContext";
/**
 * Returns blocks for the given zone and re-renders when the UI registry changes (e.g. module enable/disable).
 */
export function useUIZone(zone) {
    const runtime = useRuntime();
    const [, setTick] = useState(0);
    useEffect(() => {
        if (!runtime?.ui)
            return;
        const unsub = runtime.ui.subscribe(() => {
            setTick((t) => t + 1);
        });
        return unsub;
    }, [runtime]);
    return runtime?.ui?.getBlocksByZone(zone) ?? [];
}
